def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr, cc in ((r,c),(r,c+1),(r+1,c),(r+1,c+1))):
                blocks.append((r,c))
    for r, c in blocks:
        for rr, cc in ((r,c),(r,c+1),(r+1,c),(r+1,c+1)):
            out[rr][cc] = 2
    for r, c in blocks:
        # Diagonally adjacent corner markers rotate one place clockwise.
        corners = {
            'nw': (r-1, c-1), 'ne': (r-1, c+2),
            'se': (r+2, c+2), 'sw': (r+2, c-1),
        }
        vals = {k: grid[rc[0]][rc[1]] for k, rc in corners.items()
                if 0 <= rc[0] < h and 0 <= rc[1] < w}
        colors = {'nw': vals.get('sw', 0), 'ne': vals.get('nw', 0),
                  'se': vals.get('ne', 0), 'sw': vals.get('se', 0)}
        dirs = {'nw': (-1,-1), 'ne': (-1,1), 'se': (1,1), 'sw': (1,-1)}
        for k, (mr, mc) in corners.items():
            if k not in vals or not vals[k]:
                continue
            dr, dc = dirs[k]
            color = colors[k]
            y, x = mr, mc
            while 0 <= y < h and 0 <= x < w:
                # A down-left trail stops before it would run alongside the
                # left edge of another 2x2 marker block.
                if dr == 1 and dc == -1 and x + 1 < w and out[y][x + 1] == 2:
                    break
                out[y][x] = color
                y += dr
                x += dc
    return out
